import { dump, load } from 'js-yaml';

export interface BenchmarkHistoryEntry {
  sha: string;
  date: string;
  elaborationAvgMs: number;
  renderingAvgMs: number;
}

export const BENCHMARK_HISTORY_PATH = 'test/visual/benchmark-history.yaml';

const HEADER_LINES = [
  '# Auto-generated by `npm run benchmark:append-history` (wired into CI on',
  '# every push to master). Append-only — do not hand-edit; a PR that touches',
  '# this file is rejected by the "Reject benchmark-history.yaml edits in PRs"',
  '# CI check. See test/benchmarkHistory.ts and scripts/append-benchmark-history.ts.',
];
export const BENCHMARK_HISTORY_HEADER = HEADER_LINES.join('\n') + '\n';

function validateEntry(entry: unknown, index: number): BenchmarkHistoryEntry {
  const candidate = entry as Partial<BenchmarkHistoryEntry> | null;
  if (
    !candidate ||
    typeof candidate.sha !== 'string' ||
    typeof candidate.date !== 'string' ||
    typeof candidate.elaborationAvgMs !== 'number' ||
    typeof candidate.renderingAvgMs !== 'number'
  ) {
    throw new Error(
      `${BENCHMARK_HISTORY_PATH}[${index}] must set sha (string), date (string), ` +
        'elaborationAvgMs (number), and renderingAvgMs (number).',
    );
  }
  return candidate as BenchmarkHistoryEntry;
}

// Parses the YAML history file's content into entries, oldest first (append
// order). Empty/missing content parses to an empty list rather than throwing,
// so a freshly-seeded `[]` file and a not-yet-created one behave the same.
export function parseBenchmarkHistory(yamlText: string): BenchmarkHistoryEntry[] {
  const parsed = load(yamlText);
  if (parsed === undefined || parsed === null) return [];
  if (!Array.isArray(parsed)) {
    throw new Error(`${BENCHMARK_HISTORY_PATH} must contain a YAML list.`);
  }
  return parsed.map((entry, index) => validateEntry(entry, index));
}

// Inverse of parseBenchmarkHistory, plus the standing header comment — the
// only writer of this file (scripts/append-benchmark-history.ts) always
// round-trips through here, so the header can never drift from the entries.
export function serializeBenchmarkHistory(entries: BenchmarkHistoryEntry[]): string {
  return BENCHMARK_HISTORY_HEADER + dump(entries, { lineWidth: -1 });
}

// Append-only by construction: this is the only way to add an entry, and it
// always adds after every existing one.
export function appendBenchmarkHistoryEntry(
  existingYamlText: string,
  entry: BenchmarkHistoryEntry,
): string {
  const entries = parseBenchmarkHistory(existingYamlText);
  entries.push(entry);
  return serializeBenchmarkHistory(entries);
}

// Mean of a benchmark run's per-test values (e.g. every visual test's
// trimmed-mean elaboration or rendering duration), rounded to the nearest ms
// to match how each individual sample was already rounded
// (test/benchmarkUtils.ts's writeBenchmark/recordNamedBenchmarkSample).
export function computeRunAverageMs(entries: { value: number }[]): number {
  if (entries.length === 0) {
    throw new Error('Cannot compute a run average from zero benchmark entries.');
  }
  const mean = entries.reduce((sum, entry) => sum + entry.value, 0) / entries.length;
  return Math.round(mean);
}

// Guard-check logic for the "no hand-edits" CI gate: true when a
// `git diff --name-status -z` output (any of `M`/`A`/`D`/`Rxxx` records)
// touches the history file, either as its old or new path.
export function benchmarkHistoryChanged(nameStatusOutput: string): boolean {
  const tokens = nameStatusOutput.split('\0').filter((token) => token.length > 0);
  return tokens.includes(BENCHMARK_HISTORY_PATH);
}
